// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/customer-expansion/customers", wrapper.ListCustomers)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/customer-expansion/customers", wrapper.AddCustomer)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/customer-expansion/customers/import", wrapper.ImportCustomers)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/customer-expansion/customers/{id}", wrapper.GetCustomer)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/customer-expansion/customers/{id}", wrapper.UpdateCustomer)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/customer-expansion/customers/{id}/contracts", wrapper.ListContracts)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/customer-expansion/customers/{id}/contracts", wrapper.CreateContract)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/customer-expansion/contracts/{id}", wrapper.UpdateContract)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/customer-expansion/customers/{id}/services", wrapper.GetCoverage)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/customer-expansion/customers/{id}/services", wrapper.SetCoverage)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/customer-expansion/customers/{id}/analyze", wrapper.AnalyzeCustomer)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/customer-expansion/renewals", wrapper.ListRenewals)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/customer-expansion/renewal-alerts/{id}/acknowledge", wrapper.AcknowledgeRenewal)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/customer-expansion/recommendations", wrapper.ListRecommendations)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/customer-expansion/recommendations/{id}", wrapper.GetRecommendation)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/customer-expansion/recommendations/{id}/accept", wrapper.AcceptRecommendation)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/customer-expansion/recommendations/{id}/dismiss", wrapper.DismissRecommendation)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/customer-expansion/opportunities", wrapper.ListOpportunities)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/customer-expansion/opportunities/summary", wrapper.OpportunitySummary)
	})

	return r
}

